SELECT sc.SEC_SNAME AS `股票名称`, sc.SEC_CODE AS `股票代码`, idx.ENDDATE AS `报表截止日`, ROUND(idx.F111701, 2) AS `加权净资产收益率(%)` FROM VIEW_STK_FIN_IDX idx JOIN GET_A_SEC_CODE sc ON idx.COMCODE = sc.COMCODE AND sc.ISVALID=1 WHERE sc.SEC_SNAME LIKE '%宁德时代%' AND idx.ISVALID=1 AND idx.F111701 IS NOT NULL AND YEAR(idx.ENDDATE) = 2025 AND MONTH(idx.ENDDATE) = 12 AND DAY(idx.ENDDATE) = 31 ORDER BY idx.ENDDATE DESC LIMIT 1;
